const body = $json.body ?? $json;
const headers = $json.headers ?? {};

// Honeypot: campo oculto preenchido = bot. Encerra sem gravar nada.
if (body.site_url) {
  return null;
}

if (!body.contratante) {
  throw new Error('Payload invalido: campo "contratante" ausente.');
}

const ip = String(headers['cf-connecting-ip'] || headers['x-forwarded-for'] || '')
  .split(',')[0]
  .trim();

const crypto = require('crypto');
const hash = crypto.createHash('sha256')
  .update(JSON.stringify(body))
  .digest('hex');

const c = body.contratante;
const digitos = String(c.documento || '').replace(/\D/g, '');

const documentoFormatado = digitos.length === 14
  ? digitos.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5')
  : digitos.length === 11
    ? digitos.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4')
    : digitos;

// Carimbo em horario de Brasilia para usar nos e-mails. A coluna
// criado_em do banco fica com o default now() do Postgres.
const agora = new Date();
const registradoEmBr = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
}).format(agora).replace(', ', ' ');

return {
  json: {
    versao_contrato: body.versao_contrato,
    razao_social: c.razao_social,
    documento: digitos,
    tipo_documento: c.tipo_documento,
    responsavel: c.responsavel,
    email: c.email,
    whatsapp: c.whatsapp,
    ip,
    user_agent: body.user_agent,
    origem_pagina: body.origem_pagina,
    hash_payload: hash,

    // Campos abaixo NAO vao para o banco -- so para os e-mails.
    documento_formatado: documentoFormatado,
    registrado_em_br: registradoEmBr,
    registrado_em_iso: agora.toISOString(),
    payload_completo: JSON.stringify(body, null, 2)
  }
};

