const d = $('Normalizar Aceite').first().json;

// O no 5 substitui o json do item pelo binario, entao os dados do
// aceite sao lidos de volta pelo nome do no.
let anexos = [];
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  anexos = [{
    filename: 'contrato-kaptura-hospedagem-v1.pdf',
    content: buffer.toString('base64')
  }];
} catch (e) {
  // PDF indisponivel: manda o e-mail mesmo assim, sem anexo. O aceite ja
  // esta gravado e o cliente nao pode ficar sem confirmacao. A falha do
  // no 5 fica registrada na execucao para o time reenviar o anexo.
  anexos = [];
}

const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.6;color:#12233d;max-width:560px">'
  + '<p>Ol\u00e1, ' + d.responsavel + '!</p>'
  + '<p>Confirmamos o registro do seu aceite do Contrato de Ades\u00e3o ao Programa Kaptura (vers\u00e3o 1.0) em '
  + d.registrado_em_br + ', em nome de ' + d.razao_social + ' (' + d.documento_formatado + ').</p>'
  + '<p>O contrato completo est\u00e1 anexado neste e-mail pra sua guarda.</p>'
  + '<p><strong>Pr\u00f3ximo passo:</strong> concluir a ativa\u00e7\u00e3o da assinatura na p\u00e1gina de pagamento. '
  + 'Se voc\u00ea j\u00e1 concluiu, \u00e9 s\u00f3 aguardar: nosso time entra em contato pelo WhatsApp pra dar as '
  + 'boas-vindas e iniciar a curadoria do seu primeiro influenciador.</p>'
  + '<p>Qualquer d\u00favida, responde este e-mail.</p>'
  + '<p style="margin-top:28px"><strong>Kaptura Creators</strong><br>'
  + '<span style="color:#6b7a90">um programa Komplexa</span></p>'
  + '</div>';

return [{
  json: {
    from: 'Kaptura <contratos@kapturacreators.com.br>',
    to: [d.email],
    subject: 'Seu aceite do Contrato Kaptura foi registrado \u2705',
    html: html,
    attachments: anexos
  }
}];
